import com.example.payment.application.contact.CreateContact;
import com.example.payment.application.contact.GetContact;
import com.example.payment.infrastructure.contact.InMemoryContactRepository;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
class ContactConfiguration {

    @Bean
    ContactRepository contactRepository() {
        return new InMemoryContactRepository();
    }

    @Bean
    CreateContact createContact(ContactRepository contacts) {
        return new CreateContact(contacts);
    }

    @Bean
    GetContact getContact(ContactRepository contacts) {
        return new GetContact(contacts);
    }
}
